// ESPN public API — match events + stats for Liverpool fixtures.
// Free, no API key needed. Provides goals, cards, subs with exact minute,
// plus venue, attendance, referee, and 28 per-team match statistics.

import "server-only";
import type {
  Fixture,
  FixtureEvent,
  FixtureLineup,
  FixtureTeamStats,
  FixtureStatItem,
  LiveMatchEvent,
  LiveMatchSnapshot,
  LiveSide,
} from "@/lib/types/football";
import { getCurrentSeasonYear } from "@/lib/football/current-season";

const ESPN_BASE = "https://site.api.espn.com/apis/site/v2/sports/soccer";
const ESPN_LFC_ID = "364"; // Liverpool FC in ESPN
const FETCH_TIMEOUT_MS = 8_000;

// ESPN league slugs — all competitions Liverpool participates in
const LEAGUE_SLUGS = ["eng.1", "uefa.champions", "eng.fa", "eng.league_cup"] as const;

// ─── ESPN response shapes ───────────────────────────────────────────────────

interface EspnKeyEvent {
  type: { type: string; text: string };
  clock: { value: number; displayValue: string };
  period: { number: number };
  scoringPlay: boolean;
  team?: { id: string; displayName: string };
  participants?: { athlete: { id: string; displayName: string } }[];
  text?: string;
  shortText?: string;
}

interface EspnScheduleEvent {
  id: string;
  date: string; // ISO date
  season: { displayName: string };
  seasonType: { name: string };
  competitions: {
    venue?: { fullName?: string; address?: { city?: string } };
    status: { type: { name?: string; detail: string; state: string; completed: boolean } };
    competitors: {
      id: string;
      homeAway: string;
      winner: boolean;
      // Team schedules send an object; scoreboards send a bare string ("3").
      score?: { value: number; displayValue: string } | string;
      team: {
        id: string;
        displayName: string;
        shortDisplayName: string;
        logo?: string; // scoreboard format
        logos?: { href: string }[]; // team schedule format
      };
    }[];
  }[];
}

interface EspnBoxscoreTeam {
  team: { id: string; displayName: string };
  statistics: { name: string; displayValue: string }[];
}

interface EspnRosterEntry {
  starter: boolean;
  jersey: string;
  athlete: { id: string; displayName: string };
  position?: { abbreviation?: string; name?: string };
  formationPlace?: number | string;
}

interface EspnRosterTeam {
  team: { id: string; displayName: string; logo?: string };
  formation?: string;
  coach?: { displayName: string }[];
  roster: EspnRosterEntry[];
}

interface EspnSummary {
  header?: {
    competitions?: {
      status?: {
        displayClock?: string;
        period?: number;
        type?: { name?: string; state?: string };
      };
      competitors?: {
        homeAway?: string;
        score?: string;
        team?: {
          id?: string;
          displayName?: string;
          logo?: string;
          logos?: { href: string; rel?: string[] }[];
        };
      }[];
    }[];
  };
  keyEvents?: EspnKeyEvent[];
  commentary?: { sequence?: number; time?: { displayValue?: string }; text?: string }[];
  boxscore?: {
    teams?: EspnBoxscoreTeam[];
  };
  gameInfo?: {
    venue?: { fullName?: string; city?: string; capacity?: number };
    attendance?: number;
    officials?: { displayName?: string }[];
  };
  rosters?: EspnRosterTeam[];
}

// ─── Match detail type (venue, attendance, referee, stats) ──────────────────

export interface EspnMatchDetail {
  venue: string | null;
  attendance: number | null;
  referee: string | null;
  stats: FixtureTeamStats[];
}

// ─── Fetcher ────────────────────────────────────────────────────────────────

async function espnFetch<T>(url: string, revalidate: number): Promise<T> {
  const res = await fetch(url, {
    next: { revalidate },
    signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
  });
  if (!res.ok) throw new Error(`[espn] HTTP ${res.status} on ${url}`);
  return res.json();
}

// ─── Build date→espnId lookup from Liverpool schedule ───────────────────────

/** Map of "YYYY-MM-DD" → ESPN event ID for Liverpool matches. Cache 6h. */
async function buildDateToEspnId(): Promise<Map<string, string>> {
  const dateMap = new Map<string, string>();

  // Fetch PL + UCL schedules in parallel
  const schedules = await Promise.allSettled(
    LEAGUE_SLUGS.map((slug) =>
      espnFetch<{ events: EspnScheduleEvent[] }>(
        `${ESPN_BASE}/${slug}/teams/${ESPN_LFC_ID}/schedule`,
        21600, // 6h cache
      )
    )
  );

  for (const result of schedules) {
    if (result.status !== "fulfilled") continue;
    for (const ev of result.value.events) {
      const dateKey = ev.date.slice(0, 10); // "YYYY-MM-DD"
      dateMap.set(dateKey, ev.id);
    }
  }

  return dateMap;
}

// ─── Scoreboard fallback: find LFC match on a specific date ─────────────────

/** Check today's scoreboard for a Liverpool match (covers matches not yet in team schedule). */
async function findLfcOnScoreboard(dateKey: string): Promise<string | null> {
  const yyyymmdd = dateKey.replace(/-/g, "");
  for (const slug of LEAGUE_SLUGS) {
    try {
      const data = await espnFetch<{ events: EspnScheduleEvent[] }>(
        `${ESPN_BASE}/${slug}/scoreboard?dates=${yyyymmdd}`,
        300, // 5min cache — scoreboard updates frequently
      );
      for (const ev of data.events) {
        const comp = ev.competitions[0];
        const teamIds = comp?.competitors?.map((c) => c.team?.id) ?? [];
        if (teamIds.includes(ESPN_LFC_ID)) return ev.id;
      }
    } catch {
      continue;
    }
  }
  return null;
}

// ─── ESPN ID resolver (shared) ──────────────────────────────────────────────

async function resolveEspnId(fixtureDate: string): Promise<string | null> {
  const dateKey = fixtureDate.slice(0, 10);
  // Try team schedule first (covers past + near-future matches)
  const dateMap = await buildDateToEspnId();
  const fromSchedule = dateMap.get(dateKey);
  if (fromSchedule) return fromSchedule;
  // Fallback: check scoreboard (covers today's & upcoming matches not yet in schedule)
  return findLfcOnScoreboard(dateKey);
}

async function fetchSummary(espnId: string): Promise<EspnSummary | null> {
  for (const slug of LEAGUE_SLUGS) {
    try {
      const data = await espnFetch<EspnSummary>(
        `${ESPN_BASE}/${slug}/summary?event=${espnId}`,
        3600, // 1h cache
      );
      // Verify it has content (keyEvents or boxscore)
      if (data.keyEvents?.length || data.boxscore?.teams?.length || data.rosters?.length) {
        return data;
      }
    } catch {
      continue;
    }
  }
  return null;
}

// ─── Event type mapping ─────────────────────────────────────────────────────

/** Exported for tests. */
export function mapEventType(espnType: string): { type: FixtureEvent["type"]; detail: string } | null {
  // ESPN labels own goals "own-goal" (not "goal-…"), so they used to be dropped.
  if (espnType.startsWith("goal") || espnType === "penalty---scored" || espnType === "own-goal") {
    const detail = espnType.includes("header") ? "Header"
      : espnType.includes("penalty") ? "Penalty"
      : espnType.includes("free-kick") ? "Free Kick"
      : espnType.includes("own-goal") ? "Own Goal"
      : "Normal Goal";
    return { type: "Goal", detail };
  }
  if (espnType === "yellow-card") return { type: "Card", detail: "Yellow Card" };
  if (espnType === "red-card" || espnType === "yellow-red-card") return { type: "Card", detail: "Red Card" };
  if (espnType === "substitution") return { type: "subst", detail: "Substitution" };
  return null;
}

// Parse "61'" or "90'+2'" into { elapsed, extra }
function parseMinute(display: string): { elapsed: number; extra: number | null } {
  const match = display.match(/^(\d+)'(?:\+(\d+)')?$/);
  if (!match) return { elapsed: 0, extra: null };
  return {
    elapsed: parseInt(match[1], 10),
    extra: match[2] ? parseInt(match[2], 10) : null,
  };
}

// Extract assist name from ESPN text description
function extractAssist(text: string | undefined): string | null {
  if (!text) return null;
  const match = text.match(/Assisted by ([^.]+?)(?:\s+with\s|\s*\.)/i);
  return match ? match[1].trim() : null;
}

// ─── Stat name → display label mapping ──────────────────────────────────────

const STAT_LABEL: Record<string, string> = {
  possessionPct: "Ball Possession",
  totalShots: "Total Shots",
  shotsOnTarget: "Shots on Target",
  saves: "Saves",
  wonCorners: "Corner Kicks",
  offsides: "Offsides",
  foulsCommitted: "Fouls",
  yellowCards: "Yellow Cards",
  redCards: "Red Cards",
  totalPasses: "Total Passes",
  accuratePasses: "Accurate Passes",
  passPct: "Pass Accuracy",
  totalCrosses: "Total Crosses",
  accurateCrosses: "Accurate Crosses",
  totalLongBalls: "Long Balls",
  accurateLongBalls: "Accurate Long Balls",
  blockedShots: "Blocked Shots",
  effectiveTackles: "Tackles Won",
  totalTackles: "Total Tackles",
  interceptions: "Interceptions",
  effectiveClearance: "Clearances",
};

// Stats we want to display (in display order)
const DISPLAY_STATS = [
  "possessionPct", "totalShots", "shotsOnTarget", "saves",
  "wonCorners", "offsides", "foulsCommitted", "yellowCards", "redCards",
  "totalPasses", "accuratePasses", "passPct",
  "blockedShots", "effectiveTackles", "interceptions", "effectiveClearance",
];

function mapEspnStats(espnTeam: EspnBoxscoreTeam): FixtureTeamStats {
  const statMap = new Map((espnTeam.statistics ?? []).map((s) => [s.name, s.displayValue]));

  const statistics: FixtureStatItem[] = [];
  for (const key of DISPLAY_STATS) {
    const raw = statMap.get(key);
    if (raw === undefined) continue;

    // Format percentage stats
    let value: string | number;
    if (key === "possessionPct") {
      value = `${raw}%`;
    } else if (key === "passPct") {
      value = `${Math.round(parseFloat(raw) * 100)}%`;
    } else {
      value = parseInt(raw, 10) || 0;
    }

    statistics.push({ type: STAT_LABEL[key] ?? key, value });
  }

  return {
    team: { id: 0, name: espnTeam.team.displayName, logo: "" },
    statistics,
  };
}

// ─── Public: Fetch match events by fixture date ─────────────────────────────

/**
 * Fetch detailed match events (goals, cards, subs) with accurate minutes
 * from ESPN for a Liverpool fixture. Matches by date since IDs differ across APIs.
 */
export async function getEspnMatchEvents(fixtureDate: string): Promise<FixtureEvent[]> {
  try {
    const espnId = await resolveEspnId(fixtureDate);
    if (!espnId) return [];

    const summary = await fetchSummary(espnId);
    if (!summary?.keyEvents?.length) return [];

    const events: FixtureEvent[] = [];

    for (const ke of summary.keyEvents) {
      const mapped = mapEventType(ke.type.type);
      if (!mapped) continue;

      const minute = parseMinute(ke.clock.displayValue);
      const playerName = ke.participants?.[0]?.athlete?.displayName ?? null;
      const teamName = ke.team?.displayName ?? "";
      const assistName = mapped.type === "Goal" ? extractAssist(ke.text) : null;

      events.push({
        time: { elapsed: minute.elapsed, extra: minute.extra },
        team: { id: 0, name: teamName, logo: "" },
        player: { id: null, name: playerName },
        assist: { id: null, name: assistName },
        type: mapped.type,
        detail: mapped.detail,
        comments: null,
      });
    }

    // Sort by minute
    events.sort((a, b) => (a.time.elapsed ?? 0) - (b.time.elapsed ?? 0));

    return events;
  } catch (err) {
    console.error("[espn] getEspnMatchEvents failed:", err);
    return [];
  }
}

// ─── Public: Fetch match detail (venue, attendance, referee, stats) ────────

/**
 * Fetch match detail from ESPN for a Liverpool fixture.
 * Returns venue, attendance, referee name, and per-team match statistics.
 */
// ─── ESPN slug → canonical competition name mapping ──────────────────────────

const SLUG_COMP_NAME: Record<string, string> = {
  "eng.1": "Premier League",
  "uefa.champions": "UEFA Champions League",
  "eng.fa": "FA Cup",
  "eng.league_cup": "Carabao Cup",
};

// Local competition logos (downloaded to /public/assets/lfc/)
const SLUG_COMP_LOGO: Record<string, string> = {
  "eng.1": "/assets/lfc/premier-league-white.svg",
  "uefa.champions": "/assets/lfc/champions-league.png",
  "eng.fa": "/assets/lfc/fa-cup.png",
  "eng.league_cup": "/assets/lfc/carabao-cup.png",
};

function parseEspnScore(score: { value: number } | string | undefined): number | null {
  if (score === undefined) return null;
  const value = typeof score === "string" ? Number(score) : score.value;
  return Number.isFinite(value) ? value : null;
}

function espnTeamId(espnId: string): number {
  return espnId === ESPN_LFC_ID ? 40 : parseInt(espnId, 10);
}

// ─── Shared: map an ESPN schedule event to Fixture ─────────────────────────────

/** Exported for tests. */
export function mapEspnEventToFixture(ev: EspnScheduleEvent, compName: string, compLogo: string): Fixture | null {
  const comp = ev.competitions[0];
  if (!comp?.competitors?.length) return null;

  const home = comp.competitors.find((c) => c.homeAway === "home");
  const away = comp.competitors.find((c) => c.homeAway === "away");
  if (!home || !away) return null;

  const detail = comp.status.type.detail;
  const state = comp.status.type.state;
  const statusName = comp.status.type.name ?? "";
  // A "post" event that is not completed was postponed/cancelled, not played —
  // falling through to "FT" counted it as a finished match.
  const statusShort = statusName === "STATUS_POSTPONED" ? "PST"
    : statusName === "STATUS_CANCELED" ? "CANC"
    : detail === "FT" ? "FT"
    : detail === "AET" ? "AET"
    : detail.includes("Pens") ? "PEN"
    : state === "pre" ? "NS"
    : state === "in" ? "LIVE"
    : comp.status.type.completed ? "FT"
    : "PST";
  const statusLong = statusShort === "FT" ? "Match Finished"
    : statusShort === "AET" ? "After Extra Time"
    : statusShort === "PEN" ? "Penalties"
    : statusShort === "NS" ? "Not Started"
    : statusShort === "LIVE" ? "In Play"
    : statusShort === "PST" ? "Postponed"
    : statusShort === "CANC" ? "Cancelled"
    : detail;

  const hScore = parseEspnScore(home.score);
  const aScore = parseEspnScore(away.score);
  const isFinished = comp.status.type.completed;

  return {
    fixture: {
      id: parseInt(ev.id, 10) || Date.parse(ev.date),
      date: ev.date,
      venue: {
        id: null,
        name: comp.venue?.fullName ?? null,
        city: comp.venue?.address?.city ?? null,
      },
      status: { long: statusLong, short: statusShort, elapsed: isFinished ? 90 : null },
    },
    league: {
      id: 0,
      name: compName,
      country: "England",
      logo: compLogo,
      // From the event's own date: ESPN's team schedule also returns last
      // season's cup run, which was being labelled as the current season.
      season: getCurrentSeasonYear(new Date(ev.date)),
      round: ev.seasonType?.name ?? "",
    },
    teams: {
      home: {
        id: espnTeamId(home.team.id),
        name: home.team.displayName,
        logo: home.team.logos?.[0]?.href ?? home.team.logo ?? "",
        winner: isFinished ? home.winner : null,
      },
      away: {
        id: espnTeamId(away.team.id),
        name: away.team.displayName,
        logo: away.team.logos?.[0]?.href ?? away.team.logo ?? "",
        winner: isFinished ? away.winner : null,
      },
    },
    goals: { home: hScore, away: aScore },
    score: {
      halftime: { home: null, away: null },
      fulltime: { home: hScore, away: aScore },
      extratime: { home: null, away: null },
      penalty: { home: null, away: null },
    },
  };
}

// ─── Scoreboard: fetch upcoming cup fixtures ESPN team schedule misses ────────

/**
 * Upcoming Liverpool cup fixtures. The plain team schedule only lists played
 * matches; `?fixture=true` lists the scheduled ones. (This used to query the
 * scoreboard with a YYYYMMDD-YYYYMMDD range, which ESPN now rejects with 400,
 * so upcoming cup ties — e.g. the Carabao Cup R4 v Chelsea — never appeared.)
 */
async function getEspnUpcomingCupFixtures(): Promise<Fixture[]> {
  const cupSlugs = ["eng.fa", "eng.league_cup"] as const;
  const fixtures: Fixture[] = [];

  const results = await Promise.allSettled(
    cupSlugs.map((slug) =>
      espnFetch<{ events: EspnScheduleEvent[] }>(
        `${ESPN_BASE}/${slug}/teams/${ESPN_LFC_ID}/schedule?fixture=true`,
        21600, // 6h
      )
    )
  );

  for (let i = 0; i < cupSlugs.length; i++) {
    const result = results[i];
    if (result.status !== "fulfilled") continue;
    const slug = cupSlugs[i];
    const compName = SLUG_COMP_NAME[slug] ?? slug;
    const compLogo = SLUG_COMP_LOGO[slug] ?? "";
    for (const ev of result.value.events ?? []) {
      const fixture = mapEspnEventToFixture(ev, compName, compLogo);
      if (fixture) fixtures.push(fixture);
    }
  }

  return fixtures;
}

// ─── Public: Fetch LFC cup fixtures from ESPN ────────────────────────────────

/** Fetch Liverpool fixtures for FA Cup & EFL Cup from ESPN. Free, no key. Cache 6h. */
export async function getEspnCupFixtures(): Promise<Fixture[]> {
  const cupSlugs = ["eng.fa", "eng.league_cup"] as const;
  const fixtures: Fixture[] = [];

  // Source 1: team schedule (reliable for past matches)
  const results = await Promise.allSettled(
    cupSlugs.map((slug) =>
      espnFetch<{ events: EspnScheduleEvent[] }>(
        `${ESPN_BASE}/${slug}/teams/${ESPN_LFC_ID}/schedule`,
        21600, // 6h
      )
    )
  );

  for (let i = 0; i < cupSlugs.length; i++) {
    const result = results[i];
    if (result.status !== "fulfilled") continue;
    const slug = cupSlugs[i];
    const compName = SLUG_COMP_NAME[slug] ?? slug;
    const compLogo = SLUG_COMP_LOGO[slug] ?? "";

    for (const ev of result.value.events) {
      const fixture = mapEspnEventToFixture(ev, compName, compLogo);
      if (fixture) fixtures.push(fixture);
    }
  }

  // Source 2: scheduled fixtures (the plain schedule only has played matches)
  try {
    const upcoming = await getEspnUpcomingCupFixtures();
    const existingIds = new Set(fixtures.map((f) => f.fixture.id));
    for (const uf of upcoming) {
      if (!existingIds.has(uf.fixture.id)) {
        fixtures.push(uf);
      }
    }
  } catch (err) {
    console.error("[espn] upcoming cup fixtures failed:", err);
  }

  return fixtures;
}

// ─── Position mapping: ESPN abbreviation → canonical pos ────────────────────

function mapEspnPosition(abbr: string | undefined): string {
  const position = abbr?.toUpperCase();
  if (!position || position === "SUB") return "M"; // bench players have "SUB" — no specific position
  if (position === "G") return "G";
  if (position.includes("M")) return "M"; // M, CM, CDM, CAM, LM, RM
  if (position.includes("D") || position.includes("B")) return "D"; // D, CD, CB, LB, RB, LWB, RWB
  if (position.includes("F") || position.includes("W") || position === "ST") return "F"; // F, CF, FW, LW, RW, ST
  return "M"; // safe default
}

function parseFormation(formation: string | undefined): number[] {
  if (!formation) return [];
  return formation
    .split("-")
    .map((part) => Number(part))
    .filter((part) => Number.isFinite(part) && part > 0);
}

function getLineupRow(abbr: string | undefined, formation: string | undefined): number {
  const position = abbr?.toUpperCase() ?? "";
  const lines = parseFormation(formation);
  const maxRow = Math.max(4, lines.length + 1);
  const lastLineCount = lines.at(-1) ?? 0;

  if (!position || position === "SUB") return Math.min(3, maxRow);
  if (position === "G") return 1;
  if (position.startsWith("AM") || position === "LW" || position === "RW") return Math.max(3, maxRow - 1);
  if (position.startsWith("CF") && lastLineCount === 1 && lines.length >= 4) return Math.max(3, maxRow - 1);
  if (position.includes("F") || position === "ST") return maxRow;
  if (position === "LWB" || position === "RWB") return 2;
  if (position.includes("M") || position.includes("W")) return 3;
  if (position.includes("D") || position.includes("B")) return 2;
  return Math.min(3, maxRow);
}

function getSideWeight(abbr: string | undefined): number {
  const position = abbr?.toUpperCase() ?? "";
  if (position === "LB" || position === "LWB" || position === "LM" || position === "LW") return 1;
  if (position.endsWith("-L")) return 2;
  if (position === "RB" || position === "RWB" || position === "RM" || position === "RW") return 5;
  if (position.endsWith("-R")) return 4;
  return 3;
}

function buildStarterGrid(starters: EspnRosterEntry[], formation: string | undefined): Map<number, string> {
  const rows = new Map<number, { index: number; side: number; place: number; name: string }[]>();

  starters.forEach((player, index) => {
    const row = getLineupRow(player.position?.abbreviation, formation);
    const existing = rows.get(row) ?? [];
    existing.push({
      index,
      side: getSideWeight(player.position?.abbreviation),
      place: Number(player.formationPlace) || 99,
      name: player.athlete?.displayName ?? "",
    });
    rows.set(row, existing);
  });

  const grid = new Map<number, string>();
  for (const [row, rowPlayers] of rows.entries()) {
    rowPlayers
      .sort((a, b) => a.side - b.side || a.place - b.place || a.name.localeCompare(b.name))
      .forEach((player, columnIndex) => {
        grid.set(player.index, `${row}:${columnIndex + 1}`);
      });
  }

  return grid;
}

function getSummaryTeamLogo(summary: EspnSummary, teamId: string): string {
  const competitors = summary.header?.competitions?.[0]?.competitors ?? [];
  const team = competitors.find((competitor) => competitor.team?.id === teamId)?.team;
  return team?.logo
    ?? team?.logos?.find((logo) => logo.rel?.includes("default"))?.href
    ?? team?.logos?.[0]?.href
    ?? "";
}

// ─── Public: Fetch match lineups from ESPN roster data ──────────────────────

/**
 * Fetch match lineups (formation, starting XI, bench, coach) from ESPN
 * for a Liverpool fixture. Uses the same summary endpoint already cached.
 */
export async function getEspnMatchLineups(fixtureDate: string): Promise<FixtureLineup[]> {
  try {
    const espnId = await resolveEspnId(fixtureDate);
    if (!espnId) return [];

    const summary = await fetchSummary(espnId);
    if (!summary?.rosters?.length) return [];

    return summary.rosters.filter((r) => r.roster?.length).map((r) => {
      const starters = r.roster.filter((p) => p.starter);
      const subs = r.roster.filter((p) => !p.starter);
      const starterGrid = buildStarterGrid(starters, r.formation);

      return {
        team: {
          id: espnTeamId(r.team.id),
          name: r.team.displayName,
          logo: r.team.logo ?? getSummaryTeamLogo(summary, r.team.id),
          colors: null,
        },
        formation: r.formation ?? "",
        startXI: starters.map((p, index) => ({
          player: {
            id: parseInt(p.athlete.id, 10) || 0,
            name: p.athlete.displayName,
            number: parseInt(p.jersey, 10) || 0,
            pos: mapEspnPosition(p.position?.abbreviation),
            grid: starterGrid.get(index) ?? null,
          },
        })),
        substitutes: subs.map((p) => ({
          player: {
            id: parseInt(p.athlete.id, 10) || 0,
            name: p.athlete.displayName,
            number: parseInt(p.jersey, 10) || 0,
            pos: mapEspnPosition(p.position?.abbreviation),
            grid: null,
          },
        })),
        coach: {
          id: 0,
          name: r.coach?.[0]?.displayName ?? "",
          photo: "",
        },
      };
    });
  } catch (err) {
    console.error("[espn] getEspnMatchLineups failed:", err);
    return [];
  }
}

// ─── Public: Fetch match detail (venue, attendance, referee, stats) ────────

export async function getEspnMatchDetail(fixtureDate: string): Promise<EspnMatchDetail | null> {
  try {
    const espnId = await resolveEspnId(fixtureDate);
    if (!espnId) return null;

    const summary = await fetchSummary(espnId);
    if (!summary) return null;

    const gi = summary.gameInfo;
    const venue = gi?.venue?.fullName ?? null;
    const attendance = gi?.attendance ?? null;
    const referee = gi?.officials?.[0]?.displayName ?? null;

    const stats: FixtureTeamStats[] = (summary.boxscore?.teams ?? []).map(mapEspnStats);

    return { venue, attendance, referee, stats };
  } catch (err) {
    console.error("[espn] getEspnMatchDetail failed:", err);
    return null;
  }
}

// ─── Public: live snapshot (clock, score, goals/cards, key stats) ──────────

/** Fixture-style status for ESPN's clock state. */
function liveStatusShort(name: string, state: string, period: number): string {
  if (state === "pre") return "NS";
  if (state === "post") return name.includes("PEN") ? "PEN" : name.includes("AET") ? "AET" : "FT";
  if (name.includes("HALFTIME")) return "HT";
  if (name.includes("SHOOTOUT") || period >= 5) return "P";
  if (period >= 3) return "ET";
  return period === 2 ? "2H" : "1H";
}

const LIVE_KIND: Record<string, LiveMatchEvent["kind"]> = {
  "Penalty": "penalty",
  "Own Goal": "own-goal",
  "Yellow Card": "yellow",
  "Red Card": "red",
};

function statPair(teams: EspnBoxscoreTeam[], ids: [string, string], name: string): [number, number] {
  const read = (id: string) => {
    const raw = teams.find((t) => t.team.id === id)?.statistics.find((s) => s.name === name)?.displayValue;
    const n = Number(raw);
    return Number.isFinite(n) ? n : 0;
  };
  return [read(ids[0]), read(ids[1])];
}

/** Exported for tests. Null when the summary has no header to read the clock from. */
export function mapLiveSnapshot(summary: EspnSummary): LiveMatchSnapshot | null {
  const comp = summary.header?.competitions?.[0];
  const home = comp?.competitors?.find((c) => c.homeAway === "home");
  const away = comp?.competitors?.find((c) => c.homeAway === "away");
  if (!comp?.status || !home?.team?.id || !away?.team?.id) return null;

  const ids: [string, string] = [home.team.id, away.team.id];
  const state = comp.status.type?.state === "in" || comp.status.type?.state === "post" ? comp.status.type.state : "pre";
  const clock = comp.status.displayClock ?? "";
  const { elapsed, extra } = parseMinute(clock);
  const score = { home: parseEspnScore(home.score), away: parseEspnScore(away.score) };

  const sideOf = (team: EspnKeyEvent["team"]): LiveSide | null => {
    if (!team) return null;
    if (team.id === ids[0] || team.displayName === home.team?.displayName) return "home";
    if (team.id === ids[1] || team.displayName === away.team?.displayName) return "away";
    return null;
  };

  const events: LiveMatchEvent[] = [];
  for (const ke of summary.keyEvents ?? []) {
    const mapped = mapEventType(ke.type.type);
    const side = sideOf(ke.team);
    if (!mapped || !side || mapped.type === "subst") continue;
    const m = parseMinute(ke.clock.displayValue);
    events.push({
      side,
      kind: LIVE_KIND[mapped.detail] ?? "goal",
      minute: ke.clock.displayValue,
      at: m.elapsed + (m.extra ?? 0),
      player: ke.participants?.[0]?.athlete?.displayName ?? null,
    });
  }
  events.sort((a, b) => a.at - b.at);

  // ESPN can file an own goal under the player's team rather than the team it
  // counts for. When the scorer list disagrees with the score and flipping the
  // own goals fixes it, flip them.
  const tally = (list: LiveMatchEvent[]) => {
    const goals = list.filter((e) => e.kind === "goal" || e.kind === "penalty" || e.kind === "own-goal");
    return [goals.filter((e) => e.side === "home").length, goals.filter((e) => e.side === "away").length];
  };
  const flipped = events.map((e) => (e.kind === "own-goal" ? { ...e, side: (e.side === "home" ? "away" : "home") as LiveSide } : e));
  const [h, a] = tally(events);
  const [fh, fa] = tally(flipped);
  const ownGoalsFiled = (h !== score.home || a !== score.away) && fh === score.home && fa === score.away;

  const box = summary.boxscore?.teams ?? [];
  let stats: LiveMatchSnapshot["stats"] = null;
  if (box.length === 2) {
    const [ph, pa] = statPair(box, ids, "possessionPct");
    const possessionHome = ph + pa > 0 ? Math.round((ph / (ph + pa)) * 100) : 50;
    stats = {
      possession: [possessionHome, 100 - possessionHome],
      shots: statPair(box, ids, "totalShots"),
      onTarget: statPair(box, ids, "shotsOnTarget"),
      corners: statPair(box, ids, "wonCorners"),
    };
  }

  let latest: LiveMatchSnapshot["latest"] = null;
  let latestSeq = -1;
  for (const c of summary.commentary ?? []) {
    const minute = c.time?.displayValue;
    if (!c.text || !minute || (c.sequence ?? 0) <= latestSeq) continue;
    latest = { minute, text: c.text };
    latestSeq = c.sequence ?? 0;
  }

  return {
    state,
    statusShort: liveStatusShort(comp.status.type?.name ?? "", state, comp.status.period ?? 0),
    clock,
    minute: elapsed > 0 ? elapsed + (extra ?? 0) : null,
    score,
    events: ownGoalsFiled ? flipped : events,
    stats,
    latest,
  };
}

/**
 * Live state of a Liverpool match from ESPN, read fresh on every call (the
 * caller's CDN cache is the throttle). Football-Data.org's free tier gives no
 * match minute and lags on the score; ESPN has both, plus events and stats.
 */
export async function getEspnLiveSnapshot(fixtureDate: string): Promise<LiveMatchSnapshot | null> {
  try {
    const espnId = await resolveEspnId(fixtureDate);
    if (!espnId) return null;
    for (const slug of LEAGUE_SLUGS) {
      try {
        const res = await fetch(`${ESPN_BASE}/${slug}/summary?event=${espnId}`, {
          cache: "no-store",
          signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
        });
        if (!res.ok) continue;
        const snapshot = mapLiveSnapshot((await res.json()) as EspnSummary);
        if (snapshot) return snapshot;
      } catch {
        continue;
      }
    }
    return null;
  } catch (err) {
    console.error("[espn] getEspnLiveSnapshot failed:", err);
    return null;
  }
}
